from __future__ import annotations

import base64
import gzip
from pathlib import Path

MODULE = ""

ROOT = ""


def write(path: str, payload: str) -> None:
    Path(path).write_bytes(gzip.decompress(base64.b64decode(payload)))


write("FanoLowerBound/GeneralPositionSelection.lean", MODULE)
write("FanoLowerBound.lean", ROOT)
print("ROUND26_SOURCE_MATERIALIZED")
